import { readFileSync } from 'node:fs'
import { splitLines } from './parse.js'

const DIGEST = /^[0-9a-f]{8}$/

/** One refusal of a snapshot, carrying the message the specification words, without the `error: ` prefix. */
export class SnapshotError extends Error {
  constructor(message) {
    super(message)
    this.name = 'SnapshotError'
  }
}

/**
 * Read a digest snapshot: a line per recorded path, trimmed, with an empty line and a comment ignored.
 * @param {string} path - the snapshot file to read.
 * @returns {Map<string, string>} the recorded digest by path.
 * @throws {SnapshotError} when the file cannot be read or a line is malformed.
 */
export function readSnapshot(path) {
  let text
  try {
    text = readFileSync(path, 'utf8')
  } catch {
    throw new SnapshotError(`cannot read snapshot ${path}`)
  }
  const digests = new Map()
  splitLines(text).forEach((raw, index) => {
    const line = index + 1
    const text = raw.trim()
    if (text === '' || text.startsWith('#')) return
    const words = text.split(/\s+/u)
    if (words.length !== 2) throw new SnapshotError(`${path}: line ${line}: expected <path> <digest>`)
    const [recorded, digest] = words
    if (!DIGEST.test(digest)) throw new SnapshotError(`${path}: line ${line}: invalid digest ${digest}`)
    if (digests.has(recorded)) throw new SnapshotError(`${path}: line ${line}: path ${recorded} is recorded twice`)
    digests.set(recorded, digest)
  })
  return digests
}
"}

